-- Test suite for narrative locations (environments support)\n-- File: deploy/aruba/sql/narrative/test_locations.sql\n\nBEGIN;\n\n-- Test 1: Location CRUD operations\nDO $$\nDECLARE\n  v_owner uuid := '00000000-0000-0000-0000-000000000001'::uuid;\n  v_campaign uuid := '10000000-0000-0000-0000-000000000001'::uuid;\n  v_location uuid := '20000000-0000-0000-0000-000000000001'::uuid;\n  v_payload jsonb;\n  v_result uuid;\nBEGIN\n  -- Create test campaign and owner\n  INSERT INTO hollowgate_auth.users(id,email,status,email_verified_at) \n    VALUES(v_owner,'owner@test.local','active','2026-01-01'::timestamp)\n    ON CONFLICT(id) DO NOTHING;\n  \n  INSERT INTO hollowgate_vtt.campaigns(id,owner_id,payload) \n    VALUES(v_campaign,v_owner,'{\"name\":\"Test Campaign\"}'::jsonb)\n    ON CONFLICT(id) DO NOTHING;\n  \n  -- Test 1a: Save location\n  v_payload := jsonb_build_object(\n    'id', v_location::text,\n    'campaignId', v_campaign::text,\n    'name', 'Dark Forest',\n    'description', 'A spooky forest'\n  );\n  \n  v_result := hollowgate_vtt.save_owned_location(v_owner,v_campaign,v_location,v_payload);\n  ASSERT v_result = v_location, 'Location save failed';\n  \n  -- Test 1b: List locations\n  ASSERT EXISTS(\n    SELECT 1 FROM hollowgate_vtt.list_owned_locations(v_owner,v_campaign)\n    WHERE id=v_location\n  ), 'Location list failed';\n  \n  -- Test 1c: Delete location\n  v_result := hollowgate_vtt.delete_owned_location(v_owner,v_campaign,v_location);\n  ASSERT v_result = v_location, 'Location delete failed';\n  \n  -- Verify deletion\n  ASSERT NOT EXISTS(\n    SELECT 1 FROM hollowgate_vtt.locations \n    WHERE id=v_location AND campaign_id=v_campaign\n  ), 'Location still exists after delete';\n  \n  RAISE NOTICE 'Test 1 PASSED: Location CRUD operations';\nEND $$;\n\n-- Test 2: Authorization checks\nDO $$\nDECLARE\n  v_owner uuid := '00000000-0000-0000-0000-000000000002'::uuid;\n  v_other_owner uuid := '00000000-0000-0000-0000-000000000003'::uuid;\n  v_campaign uuid := '10000000-0000-0000-0000-000000000002'::uuid;\n  v_location uuid := '20000000-0000-0000-0000-000000000002'::uuid;\n  v_payload jsonb;\n  v_result uuid;\nBEGIN\n  -- Create owners and campaign\n  INSERT INTO hollowgate_auth.users(id,email,status,email_verified_at) \n    VALUES(v_owner,'owner2@test.local','active','2026-01-01'::timestamp),\n          (v_other_owner,'other@test.local','active','2026-01-01'::timestamp)\n    ON CONFLICT(id) DO NOTHING;\n  \n  INSERT INTO hollowgate_vtt.campaigns(id,owner_id,payload) \n    VALUES(v_campaign,v_owner,'{\"name\":\"Test Campaign 2\"}'::jsonb)\n    ON CONFLICT(id) DO NOTHING;\n  \n  v_payload := jsonb_build_object(\n    'id', v_location::text,\n    'campaignId', v_campaign::text,\n    'name', 'Forest'\n  );\n  \n  -- Owner can save\n  v_result := hollowgate_vtt.save_owned_location(v_owner,v_campaign,v_location,v_payload);\n  ASSERT v_result = v_location, 'Owner save failed';\n  \n  -- Other user cannot save (not owner)\n  v_result := hollowgate_vtt.save_owned_location(v_other_owner,v_campaign,v_location,v_payload);\n  ASSERT v_result IS NULL, 'Non-owner should not be able to save';\n  \n  -- Other user cannot delete\n  v_result := hollowgate_vtt.delete_owned_location(v_other_owner,v_campaign,v_location);\n  ASSERT v_result IS NULL, 'Non-owner should not be able to delete';\n  \n  RAISE NOTICE 'Test 2 PASSED: Authorization checks';\nEND $$;\n\n-- Test 3: Payload validation\nDO $$\nDECLARE\n  v_owner uuid := '00000000-0000-0000-0000-000000000001'::uuid;\n  v_campaign uuid := '10000000-0000-0000-0000-000000000001'::uuid;\n  v_location uuid := '20000000-0000-0000-0000-000000000003'::uuid;\n  v_result uuid;\nBEGIN\n  -- Null payload should fail\n  v_result := hollowgate_vtt.save_owned_location(v_owner,v_campaign,v_location,NULL);\n  ASSERT v_result IS NULL, 'Null payload should be rejected';\n  \n  -- Non-object payload should fail\n  v_result := hollowgate_vtt.save_owned_location(\n    v_owner,v_campaign,v_location,'\"not an object\"'::jsonb\n  );\n  ASSERT v_result IS NULL, 'Non-object payload should be rejected';\n  \n  -- Mismatched ID should fail\n  v_result := hollowgate_vtt.save_owned_location(\n    v_owner,v_campaign,v_location,\n    jsonb_build_object('id','wrong-id','campaignId',v_campaign::text)\n  );\n  ASSERT v_result IS NULL, 'Mismatched ID should be rejected';\n  \n  -- Mismatched campaign should fail\n  v_result := hollowgate_vtt.save_owned_location(\n    v_owner,v_campaign,v_location,\n    jsonb_build_object('id',v_location::text,'campaignId','wrong-campaign')\n  );\n  ASSERT v_result IS NULL, 'Mismatched campaign should be rejected';\n  \n  RAISE NOTICE 'Test 3 PASSED: Payload validation';\nEND $$;\n\n-- Test 4: Narrative reference clearing on location delete\nDO $$\nDECLARE\n  v_owner uuid := '00000000-0000-0000-0000-000000000001'::uuid;\n  v_campaign uuid := '10000000-0000-0000-0000-000000000001'::uuid;\n  v_location uuid := '20000000-0000-0000-0000-000000000004'::uuid;\n  v_npc uuid := '30000000-0000-0000-0000-000000000001'::uuid;\n  v_location_payload jsonb;\n  v_npc_payload jsonb;\nBEGIN\n  -- Create location\n  v_location_payload := jsonb_build_object(\n    'id', v_location::text,\n    'campaignId', v_campaign::text,\n    'name', 'Dark Forest'\n  );\n  \n  PERFORM hollowgate_vtt.save_owned_location(v_owner,v_campaign,v_location,v_location_payload);\n  \n  -- Create NPC with location reference\n  v_npc_payload := jsonb_build_object(\n    'id', v_npc::text,\n    'campaignId', v_campaign::text,\n    'environmentId', v_location::text,\n    'name', 'Forest Guardian'\n  );\n  \n  PERFORM hollowgate_vtt.save_owned_narrative_content(\n    v_owner,v_campaign,'npcs',v_npc,v_npc_payload\n  );\n  \n  -- Verify NPC has location reference\n  ASSERT EXISTS(\n    SELECT 1 FROM hollowgate_vtt.narrative_content_documents\n    WHERE id=v_npc AND campaign_id=v_campaign \n    AND payload->>'environmentId'=v_location::text\n  ), 'NPC location reference not set';\n  \n  -- Delete location (should clear references)\n  PERFORM hollowgate_vtt.delete_owned_location(v_owner,v_campaign,v_location);\n  \n  -- Verify NPC location reference is cleared\n  ASSERT NOT EXISTS(\n    SELECT 1 FROM hollowgate_vtt.narrative_content_documents\n    WHERE id=v_npc AND campaign_id=v_campaign \n    AND payload->>'environmentId' IS NOT NULL\n  ), 'NPC location reference not cleared after location delete';\n  \n  RAISE NOTICE 'Test 4 PASSED: Narrative reference clearing';\nEND $$;\n\nRAISE NOTICE 'All location tests PASSED';\nCOMMIT;\n"})
